module TopModule (
    input clk,
    input reset,
    output reg [3:0] q
);
    reg [3:0] gray;

    // Function to convert 4-bit Gray code to binary
    function [3:0] gray_to_binary(input [3:0] g);
        begin
            gray_to_binary[3] = g[3];
            gray_to_binary[2] = g[3] ^ g[2];
            gray_to_binary[1] = gray_to_binary[2] ^ g[1];
            gray_to_binary[0] = gray_to_binary[1] ^ g[0];
        end
    endfunction

    // Gray code increment: next_gray = gray + 1 in Gray code sequence
    // Next Gray code can be generated by XORing the current gray code with a binary incremented value:
    // Or simpler: binary = gray_to_binary(gray); binary_next = binary + 1;
    // then gray_next = binary_next ^ (binary_next >> 1);
    wire [3:0] binary;
    wire [3:0] binary_next;
    wire [3:0] gray_next;

    assign binary = gray_to_binary(gray);
    assign binary_next = binary + 1;
    assign gray_next = binary_next ^ (binary_next >> 1);

    always @(posedge clk) begin
        if (reset) begin
            gray <= 4'b0000;
            q <= 4'b0000;
        end else begin
            gray <= gray_next;
            q <= binary_next;
        end
    end
endmodule